/*
 * pixelFont.ts — a tiny 5x7 bitmap font.
 *
 * The signature look of Token Arcade comes from a hand-built 5x7 bitmap font:
 * every in-world label (COIN BANK, LVL 12, project names) is drawn pixel by
 * pixel to canvas, so nothing depends on a web font and it always reads as a
 * real pixel game rather than a webpage in a pixel typeface.
 */

import type { TextOpts } from '../core/types';

