export const GLYPH_W = 5;
export const GLYPH_H = 7;

// ---- CJK-safe path --------------------------------------------------------
// The bitmap font is ASCII-only. Any string with a character outside Latin-1
// (i.e. Chinese) is drawn/measured with canvas fillText using a system CJK font
// stack instead, so localized text never renders as `?`.
const CJK_RE = /[^�-ÿ]/;
const CJK_STACK = '"PingFang SC","Microsoft YaHei","Noto Sans CJK SC","Hiragino Sans GB",sans-serif';

/** Whether a string needs the CJK (fillText) path. */
export function isCJK(text: string | number): boolean {
  return CJK_RE.test(String(text));
}
function cjkPx(scale: number): number {
  return Math.max(8, Math.round(scale * 8));
}
function cjkFont(scale: number): string {
  return cjkPx(scale) + 'px ' + CJK_STACK;
}
// Lazy offscreen 2D context for measuring CJK width (null outside the DOM).
let _measCtx: CanvasRenderingContext2D | null | undefined;
function measCtx(): CanvasRenderingContext2D | null {
  if (_measCtx === undefined) {
    _measCtx = typeof document !== 'undefined' ? document.createElement('canvas').getContext('2d') : null;
  }
  return _measCtx ?? null;
}

/** Horizontal step from one glyph origin to the next (glyph + 1px gap). */
export function advance(scale: number): number {
  return (GLYPH_W + 1) * scale; // 1px letter spacing
}

/** Pixel width of a string once rendered (no trailing gap). CJK measured via
 * canvas metrics so wrapping/centering stays correct for Chinese. */
export function measureText(text: string, scale: number): number {
  const str = String(text);
  if (CJK_RE.test(str)) {
    const c = measCtx();
    if (c) {
      c.font = cjkFont(scale);
      return c.measureText(str).width;
    }
    return str.length * cjkPx(scale); // fallback estimate (no DOM, e.g. tests)
  }
  return str.length * advance(scale) - scale;
}

/**
 * Greedy word wrap: split on whitespace and pack words onto lines no wider than
 * maxWidth. A single word longer than maxWidth keeps its own line (never split).
 */
export function wrapText(text: string, scale: number, maxWidth: number): string[] {
  const str = String(text);
  // CJK has no spaces to break on -> wrap per character.
  if (CJK_RE.test(str)) {
    const lines: string[] = [];
    let line = '';
    for (const ch of str) {
      if (ch === '\n') {
        lines.push(line);
        line = '';
        continue;
      }
      const test = line + ch;
      if (line && measureText(test, scale) > maxWidth) {
        lines.push(line);
        line = ch;
      } else {
        line = test;
      }
    }
    if (line) lines.push(line);
    return lines;
  }
  const words = str.split(/\s+/).filter(Boolean);
  const lines: string[] = [];
  let line = '';
  for (const w of words) {
    const test = line ? line + ' ' + w : w;
    if (line && measureText(test, scale) > maxWidth) {
      lines.push(line);
      line = w;
    } else {
      line = test;
    }
  }
  if (line) lines.push(line);
  return lines;
}

// Draw pixel text. opts: { align: 'left'|'center'|'right', glow, shadow }
export function drawText(
  ctx: CanvasRenderingContext2D,
  text: string | number,
  x: number,
  y: number,
  scale: number,
  color: string,
  opts?: TextOpts,
): number {
  const o: TextOpts = opts || {};
  const raw = String(text);
  if (CJK_RE.test(raw)) return drawCJK(ctx, raw, x, y, scale, color, o);
  const str = raw.toUpperCase();
  let startX = x;
  const w = measureText(str, scale);
  if (o.align === 'center') startX = Math.round(x - w / 2);
  else if (o.align === 'right') startX = Math.round(x - w);

  if (o.shadow) {
    blit(ctx, str, startX + scale, y + scale, scale, o.shadow);
  }
  if (o.glow) {
    ctx.save();
    ctx.shadowColor = o.glow;
    ctx.shadowBlur = (o.glowBlur || 6) * scale;
    blit(ctx, str, startX, y, scale, color);
    ctx.restore();
  } else {
    blit(ctx, str, startX, y, scale, color);
  }
  return w;
}

/**
 * CJK text path: render with a system CJK font via fillText, matching the
 * bitmap path's contract — `y` is the top of the text band, alignment/glow/
 * shadow are honored, and the drawn width is returned. Not uppercased.
 */
function drawCJK(
  ctx: CanvasRenderingContext2D,
  str: string,
  x: number,
  y: number,
  scale: number,
  color: string,
  o: TextOpts,
): number {
  const px = cjkPx(scale);
  const w = measureText(str, scale);
  ctx.save();
  ctx.font = cjkFont(scale);
  ctx.textBaseline = 'top';
  ctx.textAlign = o.align === 'center' ? 'center' : o.align === 'right' ? 'right' : 'left';
  // Center the CJK glyphs within the bitmap glyph band (GLYPH_H*scale tall) so
  // Chinese lines up with adjacent pixel-font text.
  const drawY = y + (GLYPH_H * scale - px) / 2;
  if (o.shadow) {
    ctx.fillStyle = o.shadow;
    ctx.fillText(str, x + scale, drawY + scale);
  }
  ctx.fillStyle = color;
  if (o.glow) {
    ctx.shadowColor = o.glow;
    ctx.shadowBlur = (o.glowBlur || 6) * scale;
  }
  ctx.fillText(str, x, drawY);
  ctx.restore();
  return w;
}

// Stamp each glyph pixel by pixel, advancing the pen after every character.
function blit(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, scale: number, color: string): void {
  ctx.fillStyle = color;
  let cx = x;
  for (let i = 0; i < text.length; i++) {
    const glyph = FONT[text[i]] || FONT['?'];
    for (let row = 0; row < GLYPH_H; row++) {
      const line = glyph[row];
      for (let col = 0; col < GLYPH_W; col++) {
        if (line[col] === '#') {
          ctx.fillRect(cx + col * scale, y + row * scale, scale, scale);
        }
      }
    }
    cx += advance(scale);
  }
}
